    headless: true,
    herdrPresent: detectHerdrPresent(),
    ...(options.session ?? {}),
  };

  const postureFailures = [];
  const missingPoolWarnings = [];
  const otherFailures = [];
  const coverage = [];

  for (const cap of capsToCheck) {
    const unit = {
